package cn.xiaoyanjiu.ff14chat;

import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;

/** Paired connections only. Credentials stay encrypted on this phone. */
final class AccountStore {
 private static String lastSaved="";
 private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("Yanjiu.Accounts")){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("Yanjiu.Accounts",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (SecretKey)store.getKey("Yanjiu.Accounts",null);}
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"accounts.enc"));}
 private static JSONArray read(Context c)throws Exception{AtomicFile file=file(c);if(!file.getBaseFile().exists())return new JSONArray();byte[] bytes=file.readFully();return new JSONArray(AccountCipher.decrypt(bytes,key()));}
 private static void write(Context c,JSONArray accounts)throws Exception{byte[] encrypted=AccountCipher.encrypt(accounts.toString(),key());AtomicFile file=file(c);FileOutputStream stream=file.startWrite();try{stream.write(encrypted);file.finishWrite(stream);}catch(Exception e){file.failWrite(stream);throw e;}}

 static synchronized void remember(Context c,JSONObject identity){try{android.content.SharedPreferences pair=c.getSharedPreferences("pair",0);String url=pair.getString("url",""),pin=pair.getString("pin",""),token=pair.getString("token","");if(url.isEmpty()||pin.length()!=64||token.length()!=64)return;String alias=identity==null?"":identity.optString("alias"),name=identity==null?"":identity.optString("name");JSONObject game=identity==null?null:ChatService.gameAccount;String signature=url+pin+token+alias+name+(game==null?"":game.toString()+ChatService.worldAuthorized+ChatService.worldJoined+ChatService.noviceJoined);if(signature.equals(lastSaved))return;String character=game==null?"":game.optString("name")+"@"+game.optString("world");if(character.equals("@"))character="";String key=AccountIdentity.key(url,pin,token,character);JSONArray accounts=read(c);JSONObject record=null;if(character.isEmpty()){for(int i=0;i<accounts.length();i++)if(token.equals(accounts.getJSONObject(i).optString("token"))&&!accounts.getJSONObject(i).optString("characterKey").isEmpty())return;}for(int i=0;i<accounts.length();i++)if(key.equals(accounts.getJSONObject(i).optString("id"))||(token.equals(accounts.getJSONObject(i).optString("token"))&&accounts.getJSONObject(i).optString("characterKey").isEmpty()))record=accounts.getJSONObject(i);if(record==null){record=new JSONObject().put("authorizedAt",System.currentTimeMillis());accounts.put(record);}record.put("characterKey",character);record.put("id",key).put("url",url).put("pin",pin).put("token",token);if(!alias.isEmpty()&&!alias.equals("0"))record.put("alias",alias);if(!name.isEmpty())record.put("name",name);if(game!=null){if(!game.optString("name").isEmpty())record.put("gameName",game.optString("name")).put("world",game.optString("world")).put("job",game.optInt("job")).put("level",game.optInt("level"));record.put("worldAuthorized",ChatService.worldAuthorized).put("worldJoined",ChatService.worldJoined).put("noviceJoined",ChatService.noviceJoined);}write(c,accounts);pair.edit().putString("characterKey",character).apply();lastSaved=signature;}catch(Exception ignored){}}
 static synchronized String list(Context c){try{JSONArray source=read(c),safe=new JSONArray();String url=c.getSharedPreferences("pair",0).getString("url","");for(int i=0;i<source.length();i++){JSONObject a=source.getJSONObject(i);safe.put(new JSONObject().put("id",a.getString("id")).put("label",a.optString("label",a.optString("name","已授权连接"))).put("name",a.optString("name","已授权连接")).put("alias",a.optString("alias")).put("address",a.getString("url")).put("gameName",a.optString("gameName")).put("world",a.optString("world")).put("job",a.optInt("job")).put("level",a.optInt("level")).put("authorizedAt",a.optLong("authorizedAt")).put("officeAuthorized",!a.optString("officeToken").isEmpty()).put("worldAuthorized",a.optBoolean("worldAuthorized")).put("worldJoined",a.optBoolean("worldJoined")).put("noviceJoined",a.optBoolean("noviceJoined")).put("paused",c.getSharedPreferences("receiver",0).getBoolean("paused",false)).put("active",!a.optString("token").isEmpty()&&(a.optString("characterKey").isEmpty()||a.optString("characterKey").equals(c.getSharedPreferences("pair",0).getString("characterKey","")))&&url.equals(a.getString("url"))&&c.getSharedPreferences("pair",0).getString("token","").equals(a.getString("token"))));}return safe.toString();}catch(Exception e){return "[]";}}
 static synchronized void officeToken(Context c,String id,String token)throws Exception{String value=token==null?"":token.trim();if(!value.isEmpty()&&(!value.startsWith("OST_")||value.length()>4096||value.matches(".*\\s.*")))throw new IOException("请输入以OST_开头的国服频道接口令牌");JSONArray records=read(c);if(id.isEmpty()){if(value.isEmpty())throw new IOException("请输入国服频道接口令牌");records.put(new JSONObject().put("id","office:"+java.util.UUID.randomUUID()).put("label","国服离线账号").put("name","国服离线账号").put("url","").put("pin","").put("token","").put("officeToken",value).put("authorizedAt",System.currentTimeMillis()));write(c,records);return;}for(int i=0;i<records.length();i++){JSONObject a=records.getJSONObject(i);if(id.equals(a.optString("id"))){a.put("officeToken",value);write(c,records);return;}}throw new IOException("账号不存在");}
 static synchronized String officeToken(Context c,String id)throws Exception{JSONArray records=read(c);for(int i=0;i<records.length();i++){JSONObject a=records.getJSONObject(i);if(id.equals(a.optString("id"))){String value=a.optString("officeToken");if(value.isEmpty())throw new IOException("请先在账号设置配置国服频道接口令牌");return value;}}throw new IOException("账号不存在");}
 static synchronized void select(Context c,String selected)throws Exception{JSONArray source=read(c);for(int i=0;i<source.length();i++){JSONObject a=source.getJSONObject(i);if(selected.equals(a.optString("id"))){if(a.optString("url").isEmpty())throw new IOException("此账号用于国服脱机频道，无需连接电脑");c.getSharedPreferences("pair",0).edit().putString("url",a.getString("url")).putString("pin",a.getString("pin")).putString("token",a.getString("token")).putString("characterKey",a.optString("characterKey")).putString("expectedCharacterKey",a.optString("characterKey")).apply();c.getSharedPreferences("receiver",0).edit().putBoolean("paused",false).apply();return;}}throw new IOException("未找到已授权账号");}
 static synchronized void rename(Context c,String selected,String name)throws Exception{String label=name==null?"":name.trim();if(label.length()>40)throw new IOException("账号名称不能超过40个字");JSONArray records=read(c);for(int i=0;i<records.length();i++){JSONObject a=records.getJSONObject(i);if(selected.equals(a.optString("id"))){a.put("label",label.isEmpty()?"已授权账号":label);write(c,records);return;}}throw new IOException("账号不存在");}
 static synchronized void renameCurrent(Context c,String name){try{if(name==null||name.trim().isEmpty())return;String token=c.getSharedPreferences("pair",0).getString("token","");JSONArray records=read(c);for(int i=0;i<records.length();i++){JSONObject a=records.getJSONObject(i);if(token.equals(a.optString("token"))){rename(c,a.getString("id"),name);return;}}}catch(Exception ignored){}}

 static synchronized boolean remove(Context c,String selected)throws Exception{JSONArray source=read(c),remaining=new JSONArray();boolean found=false,active=false;android.content.SharedPreferences pair=c.getSharedPreferences("pair",0);for(int i=0;i<source.length();i++){JSONObject a=source.getJSONObject(i);if(selected.equals(a.optString("id"))){found=true;active=!a.optString("token").isEmpty()&&pair.getString("token","").equals(a.optString("token"))&&pair.getString("characterKey","").equals(a.optString("characterKey"));}else remaining.put(a);}if(!found)throw new IOException("账号不存在");write(c,remaining);lastSaved="";if(active)pair.edit().clear().apply();return active;}

}
